'use strict';
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3Z"/>',check:'<path d="m5 12 4 4L19 6"/>',checks:'<path d="m2 12 4 4L16 6m-4 10 9-10"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',file:'<path d="M14 3H5v18h14V8Zm0 0v6h5M8 13h8m-8 4h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5v2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bell:'<path d="M5 16V9a7 7 0 0 1 14 0v7l2 2H3Zm4 5h6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',arrowUp:'<path d="M6 18 18 6H6m12 0v12"/>',chev:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m14 5-7 7 7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h.01M13 15h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 3v4m-2-2h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3Z"/><circle cx="12" cy="14" r="4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14ZM4 20h16"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',phone:'<path d="M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4a2 2 0 0 1-2 2A18 18 0 0 1 3 5a2 2 0 0 1 2-2Z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',repeat:'<path d="M3 7h16l-4-4m6 14H5l4 4M3 7v5m18 5v-5"/>',note:'<path d="M4 3h16v13l-5 5H4Zm11 18v-5h5M8 8h8m-8 4h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',expand:'<path d="M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 10M20 3v5h-5"/>',leaf:'<path d="M4 20c14 1 17-9 16-17C8 2 0 9 4 20Zm0 0L15 9"/>',court:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="M12 5v14M3 9h18M3 15h18"/>',send:'<path d="m3 3 18 9-18 9 4-9Zm4 9h14"/>',home:'<path d="m3 10 9-7 9 7v11H3Zm6 11v-8h6v8"/>',logout:'<path d="M10 3H3v18h7m-1-9h12m-5-5 5 5-5 5"/>',pause:'<path d="M8 5v14m8-14v14"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2,8)}`;
const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const dateLabel=(date,opts={day:'numeric',month:'short'})=>date?new Date(`${String(date).slice(0,10)}T12:00:00`).toLocaleDateString('en-SG',opts):'—';
const stamp=()=>new Date().toISOString();
const humanTime=at=>{const date=String(at).slice(0,10);return date===localISO()?'Today':date===shiftDate(-1)?'Yesterday':dateLabel(date)};
const button=(label,act,ic='',kind='',attrs='')=>`<button class="btn ${kind}" data-act="${act}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const badge=(text,color='gray',ic='')=>`<span class="badge ${color}">${ic?icon(ic):''}${esc(text)}</span>`;
const statusBadge=s=>badge({approved:'Approved',review:'Needs review',queued:'Caption needed',rejected:'Changes requested'}[s]||s,{approved:'green',review:'amber',queued:'blue',rejected:'red'}[s]||'gray');
let S,db,storageMode='Opening local workspace',persistChain=Promise.resolve(),saveTimer,storageWarned=false;
function initialView(){return {role:'owner',supervisor:'s1',page:'overview',project:null,tab:'overview',query:'',filter:'all',reviewFilter:'pending',reviewProject:'all',selected:new Set(),reportProject:'p1',reportPage:0,reportId:null,reportDraft:null,reportFilter:'all',reportFrom:'',reportTo:'',reportSort:'newest',reportListPage:1};}
let V=initialView();
let pendingUploads=[],installPrompt=null,reportPreview=null,modalReturnFocus=null,uploadBusy=false,aiBusy=false;
const DB_NAME='hnh-field-reports-demo-v1';
async function initStore(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Database upgrade blocked'));});S=await new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});storageMode='Saved on this device';}catch(e){try{S=JSON.parse(localStorage.getItem(DB_NAME)||'null');storageMode='Saved on this device';}catch(_){storageMode='Session only';}}if(!S||![1,2].includes(S.schema)){S=makeSeed();await save();}else{S.photos.forEach(p=>{if(p.source)p.src=ASSET.photos[p.source]});S.reports.forEach(r=>r.photos?.forEach(p=>{if(p.source)p.src=ASSET.photos[p.source]}));if(S.schema===1){migrateWorkspace();await save();}}}
function save(){const snapshot=structuredClone(S);persistChain=persistChain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(db){const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'workspace');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}else{try{localStorage.setItem(DB_NAME,JSON.stringify(snapshot));resolve();}catch(e){reject(e);}}})).then(()=>{storageMode='Saved on this device';const el=$('#save-status');if(el)el.textContent=storageMode;}).catch(e=>{storageMode='Session only — storage unavailable';const el=$('#save-status');if(el)el.textContent=storageMode;if(!storageWarned){storageWarned=true;toast('Device storage is unavailable or full. Your latest changes will not survive a reload.','error');}console.warn('Local save failed',e);});return persistChain;}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
const isOwner=()=>V.role==='owner';
const sup=id=>S.supervisors.find(s=>s.id===id);
const project=id=>S.projects.find(p=>p.id===id);
const canAccess=p=>!!p&&(isOwner()||(sup(V.supervisor)?.active&&p.assigned.includes(V.supervisor)));
const visibleProjects=()=>S.projects.filter(canAccess);
const projectPhotos=id=>S.photos.filter(p=>p.project===id);
const visiblePhotos=()=>S.photos.filter(p=>canAccess(project(p.project))&&(isOwner()||p.supervisor===V.supervisor));
const pendingCount=id=>S.photos.filter(p=>(!id||p.project===id)&&['queued','review','rejected'].includes(p.status)).length;
const openPrompts=id=>S.notifications.filter(n=>n.kind==='prompt'&&!n.fulfilled&&(!id||n.project===id)&&canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor));
const who=()=>isOwner()?'Owner':sup(V.supervisor)?.name||'Supervisor';
function addActivity(text,pid){S.activity.unshift({id:uid('a'),project:pid,who:who(),text,at:stamp()});S.activity=S.activity.slice(0,100);}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.setAttribute('role',type==='error'?'alert':'status');el.innerHTML=icon(type==='error'?'info':'check')+`<span>${esc(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function requireOwner(){if(!isOwner()){toast('This action is available in the owner view only.','error');return false;}return true;}
const empty=(title,desc,action='',label='')=>`<div class="empty">${icon('folder')}<h3>${esc(title)}</h3>${desc?`<p>${esc(desc)}</p>`:''}${action?button(label,action,'plus','primary'):''}</div>`;
function navItems(){return isOwner()?[['overview','grid','Overview'],['projects','folder','Projects'],['review','spark','Review'],['reports','file','Reports'],['team','users','Supervisors']]:[['overview','home','Overview'],['projects','folder','My projects'],['uploads','photo','My uploads'],['inbox','bell','My prompts']];}
const HISTORY_APP='hnh-field-reports-v2';
let historyIndex=0,navigationReady=false,closingModalByButton=false,pendingHistory=null;
function viewSnapshot(){return {...V,selected:[...V.selected]};}
function restoreView(view){V={...initialView(),...view,selected:new Set(view?.selected||[])};validateView();}
function validateView(){
 if(!['owner','supervisor'].includes(V.role))V.role='owner';
 if(!isOwner()&&!sup(V.supervisor)?.active){const first=S.supervisors.find(x=>x.active);if(first)V.supervisor=first.id;else V.role='owner';}
 const allowed=isOwner()?['overview','projects','review','reports','team','inbox','report-compose','report-view']:['overview','projects','uploads','inbox'];
 if(!allowed.includes(V.page)){V.page='overview';V.project=null;}
 if(V.project&&!canAccess(project(V.project))){V.page='projects';V.project=null;}
 if(!['overview','photos'].includes(V.tab))V.tab='overview';
 if(V.page==='report-view'&&!S.reports.some(r=>r.id===V.reportId)){V.page='reports';V.reportId=null;}
 if(V.page==='report-compose'&&!project(V.reportProject)){V.page='reports';V.reportDraft=null;}
 V.selected=new Set([...V.selected].filter(id=>S.photos.some(p=>p.id===id&&p.status==='review')));
}
function routeHash(view=V){
 const parts=[view.role];if(view.role==='supervisor')parts.push(view.supervisor);
 if(view.page==='report-compose')parts.push('reports','new',view.reportProject);
 else if(view.page==='report-view')parts.push('reports',view.reportId);
 else {parts.push(view.page);if(view.project)parts.push(view.project,view.tab);}
 return '#/'+parts.map(encodeURIComponent).join('/');
}
function parseRoute(){
 let parts;try{parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean).map(decodeURIComponent);}catch{return initialView();}
 const v=initialView();if(!['owner','supervisor'].includes(parts[0]))return v;
 v.role=parts.shift();if(v.role==='supervisor')v.supervisor=parts.shift()||'s1';v.page=parts.shift()||'overview';
 if(v.page==='projects'&&parts.length){v.project=parts.shift();v.tab=parts.shift()||'overview';}
 if(v.page==='reports'&&parts[0]==='new'){v.page='report-compose';v.reportProject=parts[1]||S.projects[0]?.id;}
 else if(v.page==='reports'&&parts[0]){v.page='report-view';v.reportId=parts[0];}
 return v;
}
function syncHistoryEntry(){
 if(!navigationReady||history.state?.overlay)return;
 history.replaceState({app:HISTORY_APP,index:historyIndex,view:viewSnapshot(),scroll:window.scrollY,overlay:false},'',routeHash());
}
function navigateView(patch,{replace=false}={}){
 if(uploadBusy)return;
 clearTimeout(searchTimer);clearTimeout(reportTimer);
 const hadOverlay=!!history.state?.overlay;
 if(!hadOverlay)syncHistoryEntry();
 closeModal(true);Object.assign(V,patch);validateView();
 const replacing=replace||hadOverlay;historyIndex+=replacing?0:1;
 history[replacing?'replaceState':'pushState']({app:HISTORY_APP,index:historyIndex,view:viewSnapshot(),scroll:0,overlay:false},'',routeHash());
 render();window.scrollTo({top:0,behavior:'instant'});
}
function changePage(page,pid=null){navigateView({page,project:pid,tab:'overview',query:'',filter:'all',selected:new Set(),reportPage:0,reportListPage:1});}
function goBack(){
 if($('.modal')){closeModal();return;}
 if(historyIndex>0){history.back();return;}
 const page=V.project?'projects':['report-compose','report-view'].includes(V.page)?'reports':'overview';
 navigateView({page,project:null,tab:'overview',query:'',filter:'all',selected:new Set()},{replace:true});
}
function applyHistory(entry){
 closeModal(true);historyIndex=entry?.app===HISTORY_APP?entry.index:0;
 if(closingModalByButton){closingModalByButton=false;validateView();}
 else restoreView(entry?.app===HISTORY_APP?entry.view:parseRoute());
 // A stale form is never resurrected by Forward; only its underlying page is restored.
 history.replaceState({app:HISTORY_APP,index:historyIndex,view:viewSnapshot(),scroll:entry?.scroll||0,overlay:false},'',routeHash());
 render();requestAnimationFrame(()=>window.scrollTo({top:entry?.scroll||0,behavior:'instant'}));
}
function drainHistory(){if(pendingHistory!==null&&!uploadBusy){const entry=pendingHistory;pendingHistory=null;applyHistory(entry);return true;}return false;}
function initNavigation(){
 const entry=history.state;
 if(entry?.app===HISTORY_APP&&routeHash(entry.view)===location.hash){restoreView(entry.view);historyIndex=entry.index;}
 else restoreView(parseRoute());
 navigationReady=true;if('scrollRestoration'in history)history.scrollRestoration='manual';syncHistoryEntry();
}
window.addEventListener('popstate',e=>{if(!navigationReady)return;if(uploadBusy){pendingHistory=e.state||{};return;}applyHistory(e.state);});
window.addEventListener('hashchange',()=>{if(navigationReady&&location.hash!==routeHash()){if(uploadBusy){pendingHistory={};return;}applyHistory(null);}});
function migrateWorkspace(){
 delete S.tasks;
 S.activity=S.activity.filter(a=>! /\btask\b|\bremark\b/i.test(a.text)).map(a=>({...a,text:a.text.replace(/simulated /g,'').replace(/a demonstration report/g,'a progress report')}));
 S.notifications=S.notifications.filter(n=>!['task','remark'].includes(n.kind));
 S.photos.forEach(p=>{if(p.approvedBy==='Owner (demo)')p.approvedBy='Owner';});
 const p2=project('p2'),p3=project('p3');
 if(p2?.description?.startsWith('Demonstration project'))Object.assign(p2,{client:'Community Facilities',location:'East district · Singapore',description:'Renewal of the community sports court, including surface preparation, resurfacing and court markings.'});
 if(p3?.description?.startsWith('Fictional demonstration project'))Object.assign(p3,{client:'Landscape Facilities',location:'North district · Singapore',description:'Landscape improvement works, including site preparation, ground works and reinstatement.'});
 S.schema=2;
}
function render(){
 if(!S)return;validateView();
 const nav=navItems(),activePage=['report-compose','report-view'].includes(V.page)?'reports':V.page;
 const current=nav.find(n=>n[0]===activePage)?.[2]||(V.page==='inbox'?'Notifications':'Projects');
 const unread=S.notifications.filter(n=>!n.read&&canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).length;
 const name=who();
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand flex"><img src="${ASSET.icon}" alt="H&H Resources emblem"><div><div class="brand-name">H&H Resources</div><small>FIELD REPORTS</small></div></div><nav aria-label="Main navigation">${nav.map(([id,ic,label])=>`<button class="nav-btn ${activePage===id?'active':''}" data-act="nav" data-page="${id}" aria-label="${label}" ${activePage===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='review'&&pendingCount()?`<span class="count">${pendingCount()}</span>`:''}${id==='inbox'&&openPrompts().length?`<span class="count">${openPrompts().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="save-indicator"><span class="status-dot"></span><span id="save-status">${storageMode}</span></div>${installPrompt?`<button class="nav-btn" data-act="install" aria-label="Install app">${icon('download')}<span>Install app</span></button>`:''}<div class="profile flex"><div class="avatar dark">${isOwner()?'HH':initials(name)}</div><div><div style="font-size:12px">${esc(name)}</div><small style="font-size:10px;color:#99b09e">${isOwner()?'Owner':'Supervisor'}</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="mobile-brand"><img src="${ASSET.icon}" alt="">H&H <span style="font-weight:400;color:#78856e">Field Reports</span></div><div class="breadcrumb">Workspace ${icon('chev')} <strong>${V.project?esc(project(V.project).code):current}</strong></div><div class="top-actions"><div class="role-switch" role="group" aria-label="Switch view"><button data-act="role" data-role="owner" class="${isOwner()?'active':''}" aria-pressed="${isOwner()}">${icon('shield')}Owner</button><button data-act="role" data-role="supervisor" class="${!isOwner()?'active':''}" aria-pressed="${!isOwner()}">${icon('user')}Supervisor</button></div>${!isOwner()?`<select id="identity" aria-label="Supervisor identity">${S.supervisors.filter(s=>s.active).map(s=>`<option value="${s.id}" ${V.supervisor===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}<button class="icon-btn" data-act="inbox" aria-label="Open prompts and notifications">${icon('bell')}${unread?'<span class="notif-dot"></span>':''}</button></div></header><main class="main" id="main">${V.page!=='overview'?`<div class="back-row">${button('Back','back','left','ghost sm')}</div>`:''}${renderPage()}<footer class="footer-note"><span>H&H Resources · Field Reports</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([id,ic,label])=>`<button data-act="nav" data-page="${id}" class="${activePage===id?'active':''}" ${activePage===id?'aria-current="page"':''}>${icon(ic)}<span>${({overview:'Overview',projects:'Projects',review:'Review',reports:'Reports',team:'Team',uploads:'Uploads',inbox:'Prompts'})[id]}</span>${id==='review'&&pendingCount()?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav>`;
 if(['report-compose','report-view'].includes(V.page))setTimeout(refreshReportPreview,25);
}
function renderPage(){if(V.project)return renderProject();if(V.page==='overview')return isOwner()?ownerDashboard():supervisorDashboard();if(V.page==='projects')return projectsPage();if(V.page==='review')return reviewPage();if(V.page==='team')return teamPage();if(V.page==='reports')return reportsPage();if(V.page==='report-compose')return reportBuilder();if(V.page==='report-view')return reportViewer();if(V.page==='uploads')return uploadsPage();if(V.page==='inbox')return inboxPage();return ownerDashboard();}


function ownerDashboard(){
 const pending=S.photos.filter(p=>['review','queued','rejected'].includes(p.status)).slice(-4);
 return `<div class="page-heading"><h1>Overview</h1>${button('New project','project-new','plus','primary')}</div><div class="dashboard-grid overview-layout"><div class="stack"><section><div class="section-heading"><h2>Projects at a glance</h2><button class="text-btn" data-act="nav" data-page="projects">View all ${icon('arrow')}</button></div><div class="panel table-wrap">${projectsTable(S.projects.slice(0,5))}</div></section><section class="panel"><div class="panel-head"><h3>Latest activity</h3></div><div class="panel-body">${activityRows(S.activity.slice(0,5))}</div></section></div><section class="panel overview-review"><div class="panel-head"><h3>Review</h3>${badge(`${pendingCount()} pending`,pendingCount()?'amber':'green')}</div><div class="panel-body">${pending.length?`<div class="review-teaser">${pending.map(p=>`<button data-act="photo-open" data-id="${p.id}" aria-label="View ${esc(p.title)}"><img src="${p.src}" alt="${esc(p.title)}"></button>`).join('')}</div>`:'<div class="review-clear">'+icon('checks')+'<h3>All photos reviewed</h3></div>'}${button('Review photos','nav','spark','primary','data-page="review" style="width:100%"')}</div></section></div>`;
}
function projectsTable(projects){
 if(!projects.length)return empty('No projects','');
 return `<table class="project-table"><thead><tr><th>Project</th><th>Photo review</th><th>Team</th><th></th></tr></thead><tbody>${projects.map(p=>{const all=projectPhotos(p.id).filter(ph=>isOwner()||ph.supervisor===V.supervisor),approved=all.filter(x=>x.status==='approved').length;return `<tr class="clickable-row" data-act="project-open" data-id="${p.id}" tabindex="0" role="link" aria-label="Open ${esc(p.name)}"><td><div class="flex" style="gap:10px"><div class="project-symbol">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="">`:icon(p.category.includes('Landscape')?'leaf':'court')}</div><div><span class="project-title">${esc(p.name)}</span><div class="muted" style="font-size:10px;margin-top:4px">${esc(p.code)} · ${esc(p.status)}</div></div></div></td><td><div class="progress-cell"><div class="progress-label"><span>${approved}/${all.length} approved</span></div><div class="bar"><span style="width:${all.length?approved/all.length*100:0}%"></span></div></div></td><td><div class="avatars">${p.assigned.map(id=>`<span class="avatar" title="${esc(sup(id)?.name)}">${initials(sup(id)?.name)}</span>`).join('')}</div></td><td><span class="row-arrow">${icon('chev')}</span></td></tr>`;}).join('')}</tbody></table>`;
}
function activityRows(rows){return rows.length?rows.map(a=>`<div class="activity-row"><span class="avatar">${initials(a.who)}</span><div class="grow"><p><strong>${esc(a.who)}</strong> ${esc(a.text)}</p><small>${esc(project(a.project)?.code||'Workspace')} · ${humanTime(a.at)}</small></div></div>`).join(''):'<p class="small muted">No recent activity.</p>';}
function projectCard(p){
 const photos=projectPhotos(p.id).filter(x=>isOwner()||x.supervisor===V.supervisor),approved=photos.filter(x=>x.status==='approved').length,prompts=openPrompts(p.id);
 return `<a class="project-card" href="${routeHash({...V,page:'projects',project:p.id,tab:'overview'})}" data-act="project-open" data-id="${p.id}" aria-label="Open ${esc(p.name)}"><div class="project-card-cover">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="${esc(p.name)} field">`:`<div class="plan-art ${p.category.includes('Landscape')?'landscape':''}">${icon(p.category.includes('Landscape')?'leaf':'court')}</div>`}${badge(p.status,p.status==='Active'?'green':'gray')}</div><div class="project-card-body"><div class="eyebrow" style="font-size:8px;margin-bottom:8px">${esc(p.code)} · ${esc(p.category)}</div><h3>${esc(p.name)}</h3><p>${icon('calendar')} ${dateLabel(p.start)} — ${dateLabel(p.end)}</p><div class="flex between" style="margin:19px 0 8px"><span class="small muted" style="font-size:10px">${isOwner()?'Report approval':'My submissions'}</span><span class="small" style="font-size:10px">${approved}/${photos.length} photos approved</span></div><div class="bar"><span style="width:${photos.length?approved/photos.length*100:0}%"></span></div><div class="card-footer"><div class="avatars">${p.assigned.map(id=>`<span class="avatar" title="${esc(sup(id)?.name)}">${initials(sup(id)?.name)}</span>`).join('')}</div>${!isOwner()&&prompts.length?badge('Photo update due','amber'):''}<span class="card-open">${icon('arrow')}</span></div></div></a>`;
}
function projectsPage(){const rows=visibleProjects().filter(p=>(V.filter==='all'||p.status===V.filter)&&`${p.name} ${p.code} ${p.category}`.toLowerCase().includes(V.query.toLowerCase()));return `<div class="page-heading"><h1>${isOwner()?'Projects':'My projects'}</h1>${isOwner()?button('New project','project-new','plus','primary'):''}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search projects…" aria-label="Search projects"></label><select id="project-filter" aria-label="Project status"><option value="all">All statuses</option>${['Active','On hold','Completed'].map(s=>`<option ${V.filter===s?'selected':''}>${s}</option>`).join('')}</select></div>${rows.length?`<div class="cards-grid">${rows.map(projectCard).join('')}</div>`:empty('No matching projects','')}`;}
function supervisorDashboard(){
 const ps=visibleProjects(),photos=visiblePhotos(),pending=photos.filter(p=>p.status!=='approved'),activity=S.activity.filter(a=>ps.some(p=>p.id===a.project));
 return `<div class="page-heading"><h1>Overview</h1>${button('Upload photos','upload-open','camera','primary')}</div><div class="dashboard-grid overview-layout"><div class="stack"><section><div class="section-heading"><h2>Projects at a glance</h2><button class="text-btn" data-act="nav" data-page="projects">View all ${icon('arrow')}</button></div><div class="panel table-wrap">${projectsTable(ps)}</div></section><section class="panel"><div class="panel-head"><h3>Latest activity</h3></div><div class="panel-body">${activityRows(activity.slice(0,5))}</div></section></div><section class="panel overview-review"><div class="panel-head"><h3>Review</h3>${badge(`${pending.length} pending`,pending.length?'amber':'green')}</div><div class="panel-body">${pending.length?`<div class="review-teaser">${pending.slice(-4).map(p=>`<button data-act="photo-open" data-id="${p.id}" aria-label="View ${esc(p.title)}"><img src="${p.src}" alt="${esc(p.title)}"></button>`).join('')}</div>`:`<div class="review-clear">${icon('checks')}<h3>${photos.length?'All photos reviewed':'No submissions'}</h3></div>`}${button('View my uploads','nav','photo','primary','data-page="uploads" style="width:100%"')}</div></section></div>`;
}
function renderProject(){
 const p=project(V.project),ph=visiblePhotos().filter(x=>x.project===p.id);
 return `<section class="project-detail-banner">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="${esc(p.name)} field">`:`<div class="plan-art">${icon(p.category.includes('Landscape')?'leaf':'court')}</div>`}<div class="grow"><div class="flex wrap" style="gap:8px"><span class="eyebrow" style="font-size:9px">${esc(p.code)}</span>${badge(p.status,p.status==='Active'?'green':'gray')}</div><h1>${esc(p.name)}</h1><div class="flex wrap small muted" style="font-size:11px;gap:10px"><span>${esc(p.category)}</span><span>· ${esc(p.location)}</span></div></div><div class="flex wrap project-actions">${isOwner()?button('Edit project','project-edit','edit','',`data-id="${p.id}"`)+button('Review photos','project-review','spark','primary',`data-id="${p.id}"`):button('Upload photos','upload-open','camera','primary',`data-id="${p.id}"`)}</div></section><div class="tabs" role="tablist" aria-label="Project sections">${[['overview','Overview'],['photos','Photos']].map(([id,label])=>`<button class="tab ${V.tab===id?'active':''}" id="tab-${id}" role="tab" aria-selected="${V.tab===id}" aria-controls="project-tab-content" data-act="tab" data-tab="${id}">${label}${id==='photos'?` <span class="tab-count">${ph.length}</span>`:''}</button>`).join('')}</div><div id="project-tab-content" role="tabpanel" aria-labelledby="tab-${V.tab}">${V.tab==='overview'?projectOverview(p):`<div class="section-heading"><h2>${isOwner()?'Project photos':'My photos'}</h2>${isOwner()?button('Create report','project-report','file','',`data-id="${p.id}"`):button('Upload photos','upload-open','plus','primary',`data-id="${p.id}"`)}</div>${ph.length?`<div class="photo-grid">${ph.slice().reverse().map(photoTile).join('')}</div>`:empty('No photos','')}`}</div>`;
}
function projectOverview(p){
 const photos=projectPhotos(p.id),approved=photos.filter(x=>x.status==='approved').length;
 return `<div class="split project-overview"><div class="stack"><section class="panel"><div class="panel-head"><h3>Project brief</h3></div><div class="panel-body"><p class="description">${esc(p.description)}</p></div></section><section class="panel"><div class="panel-head"><h3>Timeline</h3>${icon('calendar')}</div><div class="panel-body"><div class="date-timeline"><div><small>Start date</small><b>${dateLabel(p.start,{day:'numeric',month:'short',year:'numeric'})}</b></div><div class="timeline-track"></div><div><small>Target date</small><b>${dateLabel(p.end,{day:'numeric',month:'short',year:'numeric'})}</b></div></div></div></section><section class="panel"><div class="panel-head"><h3>Recent activity</h3></div><div class="panel-body">${activityRows(S.activity.filter(a=>a.project===p.id).slice(0,4))}</div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h3>Scheduled prompt</h3>${icon('clock')}</div><div class="panel-body"><h2 style="font-size:22px;margin:3px 0 4px">${cadenceLabel(p)}</h2><p class="small muted">${formatTime(p.time)} · ${p.minimum} photos per update</p><div class="next-prompt"><small>Next prompt</small><strong>${nextPromptLabel(p)}</strong></div>${isOwner()?button('Prompt supervisors','prompt-now','bell','','style="width:100%;margin-top:17px" data-id="'+p.id+'"'):button('Upload photos','upload-open','camera','primary','style="width:100%;margin-top:17px" data-id="'+p.id+'"')}</div></section><section class="panel"><div class="panel-head"><h3>Report readiness</h3></div><div class="panel-body"><div class="flex between mb"><span style="font-size:27px;font-weight:600">${approved}<span class="muted" style="font-size:15px"> / ${photos.length}</span></span><span class="small muted">photos approved</span></div><div class="bar"><span style="width:${photos.length?approved/photos.length*100:0}%"></span></div>${isOwner()?button('Create report','project-report','file','','style="width:100%;margin-top:17px" data-id="'+p.id+'"'):''}</div></section><section class="panel"><div class="panel-head"><h3>Assigned supervisors</h3></div><div class="panel-body">${p.assigned.map(id=>`<div class="flex" style="margin:10px 0"><span class="avatar">${initials(sup(id)?.name)}</span><div><div style="font-size:12px">${esc(sup(id)?.name||'Former supervisor')}</div><small class="muted" style="font-size:10px">${sup(id)?.active?'Active':'Inactive'}</small></div></div>`).join('')||'<p class="small muted">No supervisors assigned.</p>'}</div></section></div></div>`;
}
function cadenceLabel(p){return {daily:'Every day',weekdays:'Weekdays',weekly:'Every '+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][p.weekday],interval:`Every ${p.interval} days`}[p.cadence]||'Every day';}
function formatTime(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`;}
function nextPrompt(p){if(p.status!=='Active')return null;const now=new Date();for(let i=0;i<500;i++){const d=new Date(`${shiftDate(i)}T${p.time}:00`),date=localISO(d);if(date<p.start||d<=now)continue;if(date>p.end)return null;const dow=d.getDay();if(p.cadence==='weekdays'&&(dow===0||dow===6))continue;if(p.cadence==='weekly'&&dow!==Number(p.weekday))continue;if(p.cadence==='interval'){const day=Math.round((new Date(date+'T12:00:00')-new Date(p.start+'T12:00:00'))/86400000);if(day%Number(p.interval)!==0)continue;}return d;}return null;}
function nextPromptLabel(p){const d=nextPrompt(p);return d?`${dateLabel(localISO(d),{weekday:'short',day:'numeric',month:'short'})} at ${formatTime(p.time)}`:'None scheduled';}



function photoTile(p){return `<article class="photo-tile"><button class="photo-image" data-act="photo-open" data-id="${p.id}" aria-label="View ${esc(p.title)}"><img src="${p.src}" loading="lazy" alt="${esc(p.title)}">${statusBadge(p.status)}</button><div class="photo-body"><span class="eyebrow" style="font-size:8px;letter-spacing:.5px">${esc(project(p.project)?.code)} · ${dateLabel(p.date)}</span><h4>${esc(p.title)}</h4><p>${esc(sup(p.supervisor)?.name||'Former supervisor')}</p>${p.status==='rejected'?`<p class="caption" style="color:var(--danger)">Owner’s note: ${esc(p.rejection||'Please provide more context.')}</p>`:''}${!isOwner()&&p.supervisor===V.supervisor&&p.status==='rejected'?button('Add clarification','photo-clarify','edit','sm','data-id="'+p.id+'" style="margin-top:9px"'):''}</div></article>`;}
function uploadsPage(){let ph=visiblePhotos().filter(p=>`${p.title} ${p.note} ${project(p.project)?.name}`.toLowerCase().includes(V.query.toLowerCase())&&(V.filter==='all'||p.status===V.filter)).reverse();return `<div class="page-heading"><div><h1>My photo uploads</h1></div>${button('Upload photos','upload-open','camera','primary')}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search my photos…" aria-label="Search photos"></label><select id="photo-filter" aria-label="Photo status"><option value="all">All statuses</option>${[['review','Needs review'],['approved','Approved'],['queued','Caption needed'],['rejected','Changes requested']].map(([k,s])=>`<option value="${k}" ${V.filter===k?'selected':''}>${s}</option>`).join('')}</select></div>${ph.length?`<div class="photo-grid">${ph.map(photoTile).join('')}</div>`:empty('No matching uploads','','upload-open','Upload photos')}`;}
function reviewRows(){return S.photos.filter(p=>(V.reviewProject==='all'||p.project===V.reviewProject)&&({pending:['review','queued','rejected'],review:['review'],approved:['approved'],queued:['queued'],rejected:['rejected'],all:['review','queued','approved','rejected']}[V.reviewFilter]||[]).includes(p.status)&&`${p.title} ${p.caption} ${project(p.project)?.name}`.toLowerCase().includes(V.query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id,undefined,{numeric:true}));}
function reviewPage(){const rows=reviewRows();const queued=rows.filter(p=>p.status==='queued').length;return `<div class="page-heading"><div><h1>Review</h1></div>${button('Generate missing','generate-missing','spark','primary',queued?'':'disabled')}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search photo captions…" aria-label="Search captions"></label><select id="review-project" aria-label="Review project"><option value="all">All projects</option>${S.projects.map(p=>`<option value="${p.id}" ${V.reviewProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="review-status" aria-label="Review status">${[['pending','All pending'],['review','Ready to review'],['queued','Caption needed'],['rejected','Changes requested'],['approved','Approved'],['all','All photos']].map(([id,label])=>`<option value="${id}" ${V.reviewFilter===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="section-heading"><span class="small muted">${rows.length} photo${rows.length!==1?'s':''} in this view</span></div>${rows.length?`<div class="review-grid">${rows.map(reviewCard).join('')}</div><div class="bulkbar"><label><input type="checkbox" id="select-all" ${rows.filter(p=>p.status==='review').length>0&&rows.filter(p=>p.status==='review').every(p=>V.selected.has(p.id))?'checked':''}> Select review-ready photos</label><div class="flex"><span class="small" style="font-size:10px" id="selected-count">${V.selected.size} selected</span>${button('Approve selected','approve-selected','checks','lime',V.selected.size?'':'disabled')}${button('Approve all visible','approve-all','check','ghost',rows.some(p=>p.status==='review')?'':'disabled')}</div></div>`:empty('No matching photos','')}`;}
function reviewCard(p){return `<article class="review-card ${V.selected.has(p.id)?'selected':''}" data-card="${p.id}"><div class="review-card-top"><label class="flex" style="gap:8px"><input type="checkbox" data-select="${p.id}" ${V.selected.has(p.id)?'checked':''} ${p.status==='review'?'':'disabled'} aria-label="Select ${esc(p.title)}"><span>${esc(project(p.project)?.code)} · ${p.source?'Photo '+String(p.source).padStart(2,'0'):'New upload'}</span></label><span data-status="${p.id}">${statusBadge(p.status)}</span></div><div class="review-image"><img src="${p.src}" alt="${esc(p.title)}" loading="lazy"><button class="icon-btn" data-act="photo-open" data-id="${p.id}" aria-label="Expand photo">${icon('expand')}</button></div><div class="review-body"><div class="flex between wrap" style="gap:6px"><h3>${esc(p.title)}</h3><span class="small muted" style="font-size:9px">${dateLabel(p.date)} · ${esc(sup(p.supervisor)?.name||'Former supervisor')}</span></div><p class="small muted" style="font-size:10px;line-height:1.65;overflow-wrap:anywhere">Site note: ${esc(p.note||'No note supplied.')}</p><div class="eyebrow">${p.status==='queued'?'CAPTION':'CAPTION'}</div><textarea data-caption="${p.id}" maxlength="420" placeholder="${p.status==='queued'?'Enter caption':'Enter caption'}" aria-label="Caption for ${esc(p.title)}">${esc(p.caption)}</textarea>${p.status==='rejected'?`<p class="small" style="font-size:10px;color:var(--danger);margin-top:5px">Changes requested: ${esc(p.rejection)}</p>`:''}</div><div class="review-card-footer"><button class="text-btn" data-act="regenerate" data-id="${p.id}" style="font-size:10px">${icon('spark')}${p.status==='queued'?'Generate draft':'Regenerate'}</button><div class="flex" style="gap:5px">${p.status!=='approved'?button('Request changes','request-changes','','ghost sm',`data-id="${p.id}"`):''}${button(p.status==='approved'?'Approved':'Approve','approve-one','check',p.status==='approved'?'sm':'sm primary',`data-id="${p.id}" ${p.status==='approved'||!p.caption.trim()?'disabled':''}`)}</div></div></article>`;}
function teamPage(){const rows=S.supervisors.filter(s=>`${s.name} ${s.email}`.toLowerCase().includes(V.query.toLowerCase())&&(V.filter==='all'||(V.filter==='active'?s.active:!s.active)));return `<div class="page-heading"><div><h1>Supervisors</h1></div>${button('Add supervisor','supervisor-new','plus','primary')}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search your team…" aria-label="Search supervisors"></label><select id="team-filter" aria-label="Supervisor status">${[['all','All supervisors'],['active','Active only'],['inactive','Inactive only']].map(([v,s])=>`<option value="${v}" ${V.filter===v?'selected':''}>${s}</option>`).join('')}</select></div>${rows.length?`<div class="cards-grid">${rows.map(s=>{const ps=S.projects.filter(p=>p.assigned.includes(s.id));return `<article class="team-card"><div class="flex between"><span class="avatar">${initials(s.name)}</span>${badge(s.active?'Active':'Inactive',s.active?'green':'gray')}</div><h3>${esc(s.name)}</h3><p class="small muted" style="font-size:10px">Site supervisor</p><div class="team-details"><span class="flex" style="gap:8px">${icon('mail')}<span class="truncate">${esc(s.email)}</span></span><span class="flex" style="gap:8px">${icon('phone')}${esc(s.phone||'No phone number')}</span></div><div class="eyebrow" style="font-size:8px;margin-bottom:9px">ASSIGNED PROJECTS · ${ps.length}</div><div class="assignment-tags">${ps.length?ps.map(p=>badge(p.code,'gray')).join(''):badge('No assignments','gray')}</div><div class="card-footer">${button('Edit supervisor','supervisor-edit','edit','sm',`data-id="${s.id}"`)}<div class="flex" style="gap:5px"><button class="icon-btn" data-act="supervisor-toggle" data-id="${s.id}" aria-label="${s.active?'Deactivate':'Activate'} ${esc(s.name)}">${icon(s.active?'pause':'check')}</button><button class="icon-btn" data-act="supervisor-delete" data-id="${s.id}" aria-label="Delete ${esc(s.name)}">${icon('trash')}</button></div></div></article>`;}).join('')}</div>`:empty('No matching supervisors','','supervisor-new','Add supervisor')}`;}
function inboxPage(){const ns=S.notifications.filter(n=>canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).slice().reverse();return `<div class="page-heading"><div><h1>${isOwner()?'Prompt activity':'My photo prompts'}</h1></div>${button('Mark all read','notifications-read','checks','')}</div><section class="panel"><div class="panel-body" style="padding-top:6px">${ns.length?ns.map(n=>`<div class="notification"><span class="avatar">${icon('bell')}</span><div class="grow"><div class="flex between wrap"><h3 style="font-size:13px">${esc(project(n.project)?.name)}</h3>${badge(n.fulfilled?'Submitted':n.kind==='prompt'?'Photos requested':'Owner update',n.fulfilled?'green':'amber')}</div><p style="margin:7px 0">${esc(n.text)}</p><small>${humanTime(n.created)} ${isOwner()?'· '+esc(sup(n.to)?.name||'Former supervisor'):''} ${n.read?'':'· Unread'}</small>${!isOwner()&&!n.fulfilled?`<div style="margin-top:11px">${n.kind==='clarification'&&n.photo?button('Clarify photo','photo-clarify','edit','sm primary',`data-id="${n.photo}"`):button('Upload photos','upload-open','camera','sm primary',`data-id="${n.project}"`)}</div>`:''}</div></div>`).join(''):empty('No prompts','')}</div></section>`;}
let confirmCallback=null;
function openModal(title,subtitle,body,footer='',size=''){
 modalReturnFocus=document.activeElement;
 if(navigationReady&&!$('.modal')){syncHistoryEntry();historyIndex++;history.pushState({app:HISTORY_APP,index:historyIndex,view:viewSnapshot(),scroll:window.scrollY,overlay:true},'',routeHash());}
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${size}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-act="modal-close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;
 document.body.style.overflow='hidden';$('#app').inert=true;
 setTimeout(()=>{const f=$('.modal input:not([type=hidden])')||$('.modal select')||$('.modal button');f?.focus();},60);
}
function closeModal(force=false){
 if(uploadBusy&&!force)return;
 const wasOpen=!!$('.modal');$('#modal-root').innerHTML='';document.body.style.overflow='';$('#app').inert=false;confirmCallback=null;pendingUploads=[];
 if(wasOpen&&!force&&history.state?.overlay){closingModalByButton=true;history.back();}
 modalReturnFocus?.isConnected&&modalReturnFocus.focus();
}
function confirmDialog(title,message,callback,label='Confirm',danger=false){openModal(title,'',`<p class="description" style="font-size:13px">${esc(message)}</p>`,button('Cancel','modal-close','','')+button(label,'confirm-action',danger?'trash':'check',danger?'danger':'primary'),'narrow');confirmCallback=callback;}
function formField(label,name,value='',type='text',extra='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function supervisorChoices(ids,field='assigned'){return `<div class="check-list">${S.supervisors.filter(s=>s.active||ids.includes(s.id)).map(s=>`<label class="check-item"><span class="avatar">${initials(s.name)}</span><span>${esc(s.name)}${s.active?'':' (inactive)'}</span><input type="checkbox" name="${field}" value="${s.id}" ${ids.includes(s.id)?'checked':''}></label>`).join('')}</div>`;}
function projectForm(id){if(!requireOwner())return;const p=id?project(id):{id:'',name:'',client:'',location:'',category:'Synthetic turf replacement',start:localISO(),end:shiftDate(30),status:'Active',assigned:[],description:'',aiInstructions:'Keep each caption factual and concise. Do not infer measurements, percentages, compliance or completion. Flag anything uncertain for owner review.',cadence:'weekdays',interval:2,weekday:5,time:'17:00',minimum:4};if(!p)return;openModal(id?'Edit project':'Start a new project','',`<form id="project-form" data-id="${p.id}"><div id="form-error" class="form-error" role="alert"></div><div class="form-section">${icon('folder')} Project details</div><div class="form-grid">${formField('Project name *','name',p.name,'text','required maxlength="110"',true)}${formField('Client / organisation *','client',p.client,'text','required maxlength="110"')}${formField('Site / location','location',p.location,'text','maxlength="140"')}<div class="field"><label for="f-category">Work category</label><select name="category" id="f-category">${['Synthetic turf replacement','Court resurfacing','Landscape works','General construction'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="f-status">Status</label><select name="status" id="f-status">${['Active','On hold','Completed'].map(c=>`<option ${p.status===c?'selected':''}>${c}</option>`).join('')}</select></div>${formField('Project start *','start',p.start,'date','required')}${formField('Target completion *','end',p.end,'date','required')}</div><div class="form-section">${icon('spark')} Project scope</div><div class="form-grid"><div class="field full"><label for="f-description">Project description / scope *</label><textarea id="f-description" name="description" required maxlength="1400" rows="4">${esc(p.description)}</textarea></div><div class="field full"><label for="f-aiInstructions">Caption guidance</label><textarea id="f-aiInstructions" name="aiInstructions" maxlength="650" rows="3">${esc(p.aiInstructions)}</textarea></div></div><div class="form-section">${icon('users')} Tag supervisors</div>${S.supervisors.some(s=>s.active)?supervisorChoices(p.assigned):'<p class="small muted">No supervisors.</p>'}<div class="form-section">${icon('bell')} Periodic photo prompts</div><div class="form-grid"><div class="field"><label for="f-cadence">How often?</label><select id="f-cadence" name="cadence">${[['daily','Every day'],['weekdays','Weekdays (Mon–Fri)'],['weekly','Weekly on a set day'],['interval','Every N days']].map(([v,l])=>`<option value="${v}" ${p.cadence===v?'selected':''}>${l}</option>`).join('')}</select></div>${formField('Prompt time','time',p.time,'time','required')}<div class="field ${p.cadence==='weekly'?'':'hidden'}" id="weekday-field"><label for="f-weekday">Day of week</label><select name="weekday" id="f-weekday">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}" ${Number(p.weekday)===i?'selected':''}>${d}</option>`).join('')}</select></div><div class="field ${p.cadence==='interval'?'':'hidden'}" id="interval-field"><label for="f-interval">Repeat every (days)</label><input name="interval" id="f-interval" type="number" min="1" max="90" value="${p.interval}"></div>${formField('Minimum photos per update','minimum',p.minimum,'number','required min="1" max="20"')}</div></form>`,`<button type="submit" class="btn primary" form="project-form">${icon('check')}${id?'Save changes':'Create project'}</button>`);}
async function saveProject(form){if(!requireOwner())return;const f=new FormData(form),id=form.dataset.id,existing=project(id);if(f.get('end')<f.get('start')){$('#form-error').textContent='Target completion must be on or after the project start date.';return;}const name=f.get('name').trim(),client=f.get('client').trim(),description=f.get('description').trim();if(!name||!client||!description){$('#form-error').textContent='Project name, client and scope must contain text.';return;}const payload={name,client,description,location:f.get('location').trim(),category:f.get('category'),start:f.get('start'),end:f.get('end'),status:f.get('status'),assigned:f.getAll('assigned').filter(id=>sup(id)),aiInstructions:f.get('aiInstructions').trim(),cadence:f.get('cadence'),interval:Math.min(90,Math.max(1,Number(f.get('interval'))||1)),weekday:Number(f.get('weekday')),time:f.get('time'),minimum:Number(f.get('minimum'))};let p;if(existing){Object.assign(existing,payload);p=existing;}else{const seq=Math.max(0,...S.projects.map(p=>Number(p.code.split('-').pop())||0))+1;p={...payload,id:uid('p'),code:`HH-026-${String(seq).padStart(3,'0')}`,hero:null,created:localISO()};S.projects.push(p);}addActivity(existing?'updated the project brief, team and reporting schedule.':'created the project and set its reporting schedule.',p.id);await save();changePage('projects',p.id);toast(existing?'Project updated.':'Project created.');}
function supervisorForm(id){if(!requireOwner())return;const s=id?sup(id):{id:'',name:'',email:'',phone:'+65 ',active:true};if(!s)return;const assigned=S.projects.filter(p=>p.assigned.includes(id)).map(p=>p.id);openModal(id?'Edit supervisor':'Add a supervisor','',`<form id="supervisor-form" data-id="${s.id}"><div id="form-error" class="form-error" role="alert"></div><div class="form-grid">${formField('Full name *','name',s.name,'text','required maxlength="70"',true)}${formField('Email address *','email',s.email,'email','required maxlength="120"')}${formField('Mobile number','phone',s.phone,'tel','maxlength="30"')}<div class="field full"><label class="check-item"><span>Active supervisor</span><input name="active" type="checkbox" ${s.active?'checked':''}></label></div></div><div class="form-section">${icon('folder')} Assigned projects</div><div class="check-list">${S.projects.map(p=>`<label class="check-item"><span class="grow">${esc(p.name)}<br><small class="muted">${esc(p.code)}</small></span><input type="checkbox" name="projects" value="${p.id}" ${assigned.includes(p.id)?'checked':''}></label>`).join('')||'<p class="small muted">No projects.</p>'}</div></form>`,button('Cancel','modal-close')+`<button class="btn primary" type="submit" form="supervisor-form">${icon('check')}${id?'Save changes':'Add supervisor'}</button>`);}
async function saveSupervisor(form){if(!requireOwner())return;const f=new FormData(form),id=form.dataset.id,name=f.get('name').trim(),email=f.get('email').trim().toLowerCase();if(!name){$('#form-error').textContent='Enter a supervisor name.';return;}if(S.supervisors.some(s=>s.email.toLowerCase()===email&&s.id!==id)){$('#form-error').textContent='That email is already used by another supervisor.';return;}const data={name,email,phone:f.get('phone').trim(),active:f.has('active')};let s=sup(id);if(s)Object.assign(s,data);else{s={id:uid('s'),...data};S.supervisors.push(s);}const projectIds=f.getAll('projects');S.projects.forEach(p=>{p.assigned=p.assigned.filter(x=>x!==s.id);if(projectIds.includes(p.id))p.assigned.push(s.id);});addActivity(`${id?'updated':'added'} supervisor ${name}.`,projectIds[0]||null);await save();closeModal();render();toast(`${name} ${id?'updated':'added'}.`);}




async function sendPrompt(pid){
 if(!requireOwner())return;const p=project(pid);if(!p)return;const recipients=p.assigned.filter(id=>sup(id)?.active);
 if(!recipients.length){toast('No active supervisors assigned.','error');return;}
 for(const id of recipients)S.notifications.push({id:uid('n'),project:pid,to:id,kind:'prompt',text:`Please submit at least ${p.minimum} progress photos for ${p.name}.`,created:stamp(),read:false,fulfilled:false,minimum:p.minimum});
 addActivity(`requested photo updates from ${recipients.length} supervisor${recipients.length!==1?'s':''}.`,pid);await save();render();toast(`Photo request added to ${recipients.length} inbox${recipients.length!==1?'es':''}.`);
}
function uploadForm(pid){if(isOwner()){toast('Switch to the supervisor view to submit a site update.','error');return;}const ps=visibleProjects();if(!ps.length){toast('This supervisor has no assigned projects.','error');return;}const p=ps.find(p=>p.id===pid)||ps[0];pendingUploads=[];openModal('Submit a site update','',`<form id="upload-form"><div id="form-error" class="form-error" role="alert"></div><div class="form-grid"><div class="field full"><label for="upload-project">Assigned project *</label><select name="project" id="upload-project">${ps.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label for="upload-stage">Work stage *</label><select name="stage" id="upload-stage">${STAGES.map(s=>`<option ${s==='Joining & gamelines'?'selected':''}>${s}</option>`).join('')}</select></div>${formField('Photo record date *','date',localISO(),'date','required max="'+localISO()+'"')}</div><div class="upload-drop mt" id="upload-drop">${icon('camera')}<h3>Add your site photos</h3><p>JPEG, PNG, WebP · 20 photos maximum · 15 MB per photo</p><div class="flex wrap" style="justify-content:center">${button('Choose photos','choose-files','upload','primary')}${button('Take a photo','take-photo','camera','')}</div><input id="upload-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><input id="camera-file" type="file" accept="image/*" capture="environment" hidden></div><div class="upload-thumbs" id="upload-thumbs"></div><div class="field mt"><label for="upload-note">Site note / context for this update</label><textarea id="upload-note" name="note" maxlength="500" rows="3"></textarea></div><label class="check-item mt"><span class="grow">Generate draft captions after upload</span><input type="checkbox" name="generate" checked></label></form>`,button('Cancel','modal-close')+`<button type="submit" class="btn primary" form="upload-form" id="upload-submit">${icon('upload')}Submit update</button>`);const drop=$('#upload-drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragging')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragging');addFiles(e.dataTransfer.files)});}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('The image could not be decoded.'));im.src=src;});}
async function resizeFile(file){if(file.size>15*1024*1024)throw new Error(`${file.name}: over the 15 MB limit.`);if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error(`${file.name}: use JPEG, PNG or WebP. Convert HEIC photos first.`);const url=URL.createObjectURL(file);try{const im=await loadImage(url);const scale=Math.min(1,1600/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));const ctx=c.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);return {id:uid('temp'),src:c.toDataURL('image/jpeg',.88),fileName:file.name,note:'',source:null};}finally{URL.revokeObjectURL(url);}}
async function addFiles(files){if(uploadBusy)return;const room=20-pendingUploads.length;if(room<=0){toast('A single update can contain up to 20 photos.','error');return;}if(files.length>room)toast(`Only the first ${room} additional photos will be added.`);uploadBusy=true;const submit=$('#upload-submit');if(submit)submit.disabled=true;try{for(const file of [...files].slice(0,room)){try{pendingUploads.push(await resizeFile(file));}catch(e){toast(e.message,'error');}}renderUploadThumbs();}finally{uploadBusy=false;if(submit)submit.disabled=false;drainHistory();}}
function renderUploadThumbs(){const el=$('#upload-thumbs');if(!el)return;el.innerHTML=pendingUploads.map((p,i)=>`<div class="upload-thumb"><img src="${p.src}" alt="Photo ${i+1} preview"><button type="button" class="icon-btn" data-act="upload-remove" data-id="${p.id}" aria-label="Remove photo ${i+1}">${icon('close')}</button><p>${esc(p.fileName)}</p><textarea class="upload-note" maxlength="220" data-upload-note="${p.id}" aria-label="Note for photo ${i+1}" placeholder="Specific note (optional)">${esc(p.note)}</textarea></div>`).join('');}

function draftCaption(ph){const p=project(ph.project);if(ph.source)return SAMPLE_CAPTIONS[ph.source-1];const note=String(ph.note||'').trim().replace(/\s+/g,' ');const context=String(p?.description||'').trim().split(/[.!?](?:\s|$)/)[0];let text=`${ph.stage}: site-progress photograph for ${p?.name||'the project'}.`;if(note)text+=` Site note: ${note.replace(/[.!?]$/,'')}.`;else text+=' No specific activity was supplied; owner clarification is required.';if(context&&text.length<245)text+=` Scope context: ${context.slice(0,140)}.`;if(text.length>420)text=text.slice(0,417)+'…';return text;}
async function submitUpload(form){if(uploadBusy||isOwner())return;const f=new FormData(form),pid=f.get('project'),p=project(pid);if(!canAccess(p)){$('#form-error').textContent='You are not assigned to that project.';return;}if(!pendingUploads.length){$('#form-error').textContent='Add at least one photograph before submitting.';return;}if(f.get('date')>localISO()){$('#form-error').textContent='The photo record date cannot be in the future.';return;}if(pendingUploads.some(ph=>ph.source)&&pid!=='p1'){$('#form-error').textContent='The SACPS sample photos cannot be submitted under another project.';return;}uploadBusy=true;const btn=$('#upload-submit');btn.disabled=true;btn.innerHTML=icon('refresh')+' Saving update…';const count=pendingUploads.length;try{const newPhotos=pendingUploads.map(ph=>{const note=[ph.note,f.get('note').trim()].filter(Boolean).join(' — ').slice(0,720);const item={id:uid('ph'),project:pid,supervisor:V.supervisor,src:ph.src,source:ph.source,fileName:ph.fileName,stage:ph.source?SOURCE_STAGE(ph.source):f.get('stage'),title:ph.source?SOURCE_TITLES[ph.source-1]:f.get('stage'),note,date:f.get('date'),uploadedAt:stamp(),status:f.has('generate')?'review':'queued',caption:'',approvedBy:null,approvedAt:null,revision:1};if(f.has('generate'))item.caption=draftCaption(item);return item;});await new Promise(r=>setTimeout(r,650));S.photos.push(...newPhotos);S.notifications.forEach(n=>{if(n.to===V.supervisor&&n.project===pid&&n.kind==='prompt'&&!n.fulfilled){n.submittedCount=(n.submittedCount||0)+count;n.fulfilled=n.submittedCount>=(n.minimum||p.minimum);n.read=true;}});addActivity(`submitted ${count} photo${count!==1?'s':''}${f.has('generate')?' with draft captions':''}.`,pid);await save();uploadBusy=false;if(!drainHistory())changePage('uploads');toast(`${count} photo${count!==1?'s':''} submitted. ${f.has('generate')?'Awaiting review.':'Captions pending.'}`);}catch(e){uploadBusy=false;btn.disabled=false;btn.innerHTML=icon('upload')+'Submit update';toast('The update could not be saved. Please try again.','error');console.error(e);}}
function photoModal(id){const ph=S.photos.find(p=>p.id===id);if(!ph||!canAccess(project(ph.project))||(!isOwner()&&ph.supervisor!==V.supervisor))return;openModal(esc(ph.title),`${esc(project(ph.project)?.code)} · ${dateLabel(ph.date)} · ${esc(sup(ph.supervisor)?.name||'Former supervisor')}`,`<img class="lightbox-image" src="${ph.src}" alt="${esc(ph.title)}"><div class="flex wrap mb">${statusBadge(ph.status)}${badge(ph.stage,'gray')}${ph.source?badge(`Photo ${ph.source}`,'gray'):''}</div><p class="lightbox-caption">${esc(ph.caption||'Caption not generated yet.')}</p><p class="small muted mt" style="white-space:pre-wrap;overflow-wrap:anywhere">Site note: ${esc(ph.note||'None')}</p>`,button('Close','modal-close'),'wide');}
async function generateCaptions(ids){if(!requireOwner()||aiBusy)return;const list=S.photos.filter(p=>ids.includes(p.id));if(!list.length){toast('No photos need captions in this view.');return;}aiBusy=true;toast(`Generating ${list.length} draft caption${list.length!==1?'s':''}…`);await new Promise(r=>setTimeout(r,750));for(const ph of list){ph.caption=draftCaption(ph);ph.status='review';ph.approvedAt=null;ph.approvedBy=null;ph.revision++;delete ph.rejection;}addActivity(`generated ${list.length} caption draft${list.length!==1?'s':''}.`,list[0].project);await save();aiBusy=false;render();toast('Draft captions ready.');}
async function approvePhotos(ids){if(!requireOwner())return;const eligible=S.photos.filter(p=>ids.includes(p.id)&&p.caption.trim()&&p.status==='review');if(!eligible.length){toast('Only review-ready captions can be approved.','error');return;}eligible.forEach(p=>{p.status='approved';p.approvedBy='Owner';p.approvedAt=stamp();V.selected.delete(p.id)});addActivity(`approved ${eligible.length} caption${eligible.length!==1?'s':''} for PDF export.`,eligible[0].project);await save();render();toast(`${eligible.length} photo caption${eligible.length!==1?'s':''} approved for reports.`);}
function approveConfirmation(ids){const list=S.photos.filter(p=>ids.includes(p.id)&&p.caption.trim()&&p.status==='review');if(!list.length){toast('Select review-ready captions first.','error');return;}confirmDialog('Confirm your caption review',`Approve ${list.length} photo caption${list.length!==1?'s':''}?`,()=>approvePhotos(list.map(p=>p.id)),'Approve captions');}
function requestChanges(id){if(!requireOwner())return;const ph=S.photos.find(p=>p.id===id);if(!ph)return;openModal('Ask for clarification',esc(ph.title),`<form id="changes-form" data-id="${id}"><div class="field"><label for="change-note">What should the supervisor clarify? *</label><textarea id="change-note" name="reason" required maxlength="500"></textarea></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" form="changes-form" type="submit">${icon('send')}Request changes</button>`,'narrow');}
function clarificationForm(id){const ph=S.photos.find(p=>p.id===id);if(!ph||isOwner()||ph.supervisor!==V.supervisor||!canAccess(project(ph.project)))return;openModal('Clarify this photo',esc(ph.title),`<div class="notice amber">${icon('note')}<span>${esc(ph.rejection||'Please add the missing context.')}</span></div><form id="clarify-form" data-id="${id}"><div class="field"><label for="clarify-note">Updated site note *</label><textarea id="clarify-note" name="note" required maxlength="700">${esc(ph.note)}</textarea></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" form="clarify-form" type="submit">${icon('send')}Resubmit for review</button>`,'narrow');}
function reportRows(){
 const q=V.query.trim().toLowerCase();
 return S.reports.filter(r=>(V.reportFilter==='all'||r.project===V.reportFilter)&&(!V.reportFrom||String(r.exported).slice(0,10)>=V.reportFrom)&&(!V.reportTo||String(r.exported).slice(0,10)<=V.reportTo)&&`${r.projectName} ${r.code} ${r.reference} ${r.client}`.toLowerCase().includes(q)).sort((a,b)=>V.reportSort==='oldest'?a.exported.localeCompare(b.exported):b.exported.localeCompare(a.exported));
}
function reportsPage(){
 const rows=reportRows(),size=8,total=Math.max(1,Math.ceil(rows.length/size));V.reportListPage=Math.max(1,Math.min(V.reportListPage,total));const list=rows.slice((V.reportListPage-1)*size,V.reportListPage*size);
 const projects=[...new Map(S.reports.map(r=>[r.project,r.projectName])).entries()];
 return `<div class="page-heading"><h1>Reports</h1></div><div class="filterbar report-filters"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search reports…" aria-label="Search reports"></label><select id="archive-project" aria-label="Filter reports by project"><option value="all">All projects</option>${projects.map(([id,name])=>`<option value="${id}" ${V.reportFilter===id?'selected':''}>${esc(name)}</option>`).join('')}</select><label class="date-filter"><span>Exported from</span><input type="date" id="archive-from" value="${V.reportFrom}" aria-label="Exported from"></label><label class="date-filter"><span>Exported to</span><input type="date" id="archive-to" value="${V.reportTo}" aria-label="Exported to"></label><select id="archive-sort" aria-label="Sort reports"><option value="newest" ${V.reportSort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${V.reportSort==='oldest'?'selected':''}>Oldest first</option></select></div>${V.reportFrom&&V.reportTo&&V.reportFrom>V.reportTo?'<p class="form-error" role="alert">The end date must be on or after the start date.</p>':''}<div class="section-heading"><span class="small muted">${rows.length} report${rows.length!==1?'s':''}</span>${V.query||V.reportFilter!=='all'||V.reportFrom||V.reportTo?'<button class="text-btn" data-act="report-clear">Clear filters</button>':''}</div><section class="panel report-list">${list.length?`<div class="report-list-head"><span>Report / project</span><span>Reporting period</span><span>Photos</span><span>Exported</span><span></span></div>${list.map(r=>`<article class="report-list-row"><a class="report-name-cell" data-act="report-open" data-id="${r.id}" href="${routeHash({...V,page:'report-view',reportId:r.id,project:null})}"><span class="report-file-icon">${icon('file')}</span><div><h3>${esc(r.reference||'Progress report')}</h3><p>${esc(r.projectName)}</p><small>${esc(r.code)}</small></div></a><div class="report-period"><span class="mobile-cell-label">Period</span>${dateLabel(r.from,{day:'numeric',month:'short',year:'numeric'})}<br><span class="muted">to ${dateLabel(r.to,{day:'numeric',month:'short',year:'numeric'})}</span></div><div class="report-photos"><span class="mobile-cell-label">Photos</span>${r.photos.length}</div><div class="report-exported"><span class="mobile-cell-label">Exported</span>${dateLabel(r.exported,{day:'numeric',month:'short',year:'numeric'})}</div><div class="report-row-actions">${button('View','report-open','eye','sm',`data-id="${r.id}"`)}<button class="icon-btn" data-act="report-redownload" data-id="${r.id}" aria-label="Download ${esc(r.reference||r.code)}">${icon('download')}</button><button class="icon-btn" data-act="report-delete" data-id="${r.id}" aria-label="Delete ${esc(r.reference||r.code)}">${icon('trash')}</button></div></article>`).join('')}`:empty('No reports found','')}</section>${rows.length>size?`<div class="pagination">${button('Previous','archive-prev','left','sm',V.reportListPage===1?'disabled':'')}<span>Page ${V.reportListPage} of ${total}</span>${button('Next','archive-next','chev','sm',V.reportListPage===total?'disabled':'')}</div>`:''}`;
}
function ensureReportDraft(){
 const p=project(V.reportProject);if(!p)return null;
 if(!V.reportDraft||V.reportDraft.project!==p.id)V.reportDraft={project:p.id,from:p.start,to:p.end<localISO()?p.end:localISO(),client:p.client,reference:'',summary:''};
 return V.reportDraft;
}
function reportBuilder(){
 const p=project(V.reportProject),d=ensureReportDraft();if(!p||!d)return empty('Project unavailable','');
 return `<div class="page-heading"><div><h1>Create report</h1><p class="record-subtitle">${esc(p.name)}</p></div></div><div class="report-layout"><section class="panel report-control"><h3 style="margin-bottom:19px">Report details</h3><div class="field"><label for="report-project">Project</label><select id="report-project">${S.projects.map(p=>`<option value="${p.id}" ${V.reportProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="inline-pair"><div class="field"><label for="report-from">From</label><input type="date" id="report-from" value="${d.from}"></div><div class="field"><label for="report-to">To</label><input type="date" id="report-to" value="${d.to}"></div></div><div class="field"><label for="report-client">Prepared for</label><input id="report-client" maxlength="110" value="${esc(d.client)}"></div><div class="field"><label for="report-ref">Claim / reference</label><input id="report-ref" maxlength="70" value="${esc(d.reference)}"></div><div class="field"><label for="report-summary">Report summary</label><textarea id="report-summary" maxlength="600" rows="4">${esc(d.summary)}</textarea></div><div class="report-readiness" id="report-readiness"></div>${button('Export PDF','report-export','download','primary','style="width:100%" id="export-pdf"')}</section>${reportPreviewShell()}</div>`;
}
function reportPreviewShell(){return `<section class="report-preview"><div id="report-canvas" style="width:100%;display:flex;justify-content:center"><p class="muted small">Loading preview…</p></div><div class="report-nav">${button('Previous','report-prev','left','sm','id="report-prev"')}<span id="report-page-count">Page 1</span>${button('Next','report-next','chev','sm','id="report-next"')}</div></section>`;}
function reportViewer(){
 const r=S.reports.find(r=>r.id===V.reportId);if(!r)return empty('Report unavailable','');
 return `<div class="page-heading"><div><h1>${esc(r.reference||'Progress report')}</h1><p class="record-subtitle">${esc(r.projectName)}</p></div>${button('Download PDF','report-redownload','download','primary',`data-id="${r.id}"`)}</div><div class="report-record-meta">${badge('Exported','green')}<span>${dateLabel(r.from,{day:'numeric',month:'short',year:'numeric'})} — ${dateLabel(r.to,{day:'numeric',month:'short',year:'numeric'})}</span><span>${r.photos.length} photos</span></div><div class="archive-preview">${reportPreviewShell()}</div>`;
}
function getReportSnapshot(){
 const p=project(V.reportProject),d=ensureReportDraft();if(!p||!d)return null;
 const range=projectPhotos(p.id).filter(ph=>ph.date>=d.from&&ph.date<=d.to);
 return {id:uid('r'),project:p.id,projectName:p.name,code:p.code,category:p.category,client:d.client.trim()||p.client,reference:d.reference.trim(),summary:d.summary.trim(),from:d.from,to:d.to,exported:stamp(),photos:structuredClone(range.filter(ph=>ph.status==='approved'&&ph.caption.trim()).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id,undefined,{numeric:true}))).map(ph=>({...ph,supervisorName:sup(ph.supervisor)?.name||'Former supervisor'})),excluded:range.filter(ph=>ph.status!=='approved'||!ph.caption.trim()).length};
}
let previewToken=0;
async function refreshReportPreview(){
 if(!['report-compose','report-view'].includes(V.page)||!$('#report-canvas'))return;
 const token=++previewToken,r=V.page==='report-view'?S.reports.find(r=>r.id===V.reportId):getReportSnapshot();if(!r)return;reportPreview=r;
 const invalid=!r.from||!r.to||r.from>r.to,ready=$('#report-readiness'),exportBtn=$('#export-pdf');
 if(ready)ready.innerHTML=invalid?'<span class="form-error">Select a valid reporting period.</span>':`<strong>${r.photos.length} approved photos</strong><span>${r.excluded} awaiting approval</span>`;
 if(exportBtn)exportBtn.disabled=invalid||r.photos.length===0;
 const total=1+Math.ceil(r.photos.length/4);V.reportPage=Math.max(0,Math.min(V.reportPage,total-1));
 try{const canvas=await drawReportPage(r,V.reportPage);if(token!==previewToken||!$('#report-canvas'))return;$('#report-canvas').replaceChildren(canvas);$('#report-page-count').textContent=`Page ${V.reportPage+1} of ${total}`;$('#report-prev').disabled=V.reportPage===0;$('#report-next').disabled=V.reportPage===total-1;}catch(e){if($('#report-canvas'))$('#report-canvas').innerHTML='<p class="small muted">Preview unavailable.</p>';toast('A report photograph could not load.','error');console.error(e);}
}
const imageCache=new Map();async function reportImage(src){if(!imageCache.has(src))imageCache.set(src,loadImage(src));return imageCache.get(src);}
function canvasText(ctx,text,x,y,maxWidth,{font=10,color='#253c2c',weight=400,line=1.45,maxLines=99}={}){ctx.fillStyle=color;ctx.font=`${weight} ${font}px Arial,sans-serif`;ctx.textBaseline='top';const lines=[];for(const para of String(text||'').split('\n')){let row='';for(const word of para.split(/\s+/)){if(!word)continue;const candidate=row?row+' '+word:word;if(ctx.measureText(candidate).width<=maxWidth){row=candidate;continue;}if(row){lines.push(row);row='';}if(ctx.measureText(word).width<=maxWidth)row=word;else{let part='';for(const char of word){if(ctx.measureText(part+char).width>maxWidth){lines.push(part);part=char;}else part+=char;}row=part;}}lines.push(row);}if(lines.length>maxLines){const last=lines.slice(0,maxLines);last[maxLines-1]=last[maxLines-1].replace(/\s+\S*$/,'')+'…';last.forEach((s,i)=>ctx.fillText(s,x,y+i*font*line));return {height:last.length*font*line,lines:lines.length};}lines.forEach((s,i)=>ctx.fillText(s,x,y+i*font*line));return {height:lines.length*font*line,lines:lines.length};}
function measureLines(ctx,text,w,font){ctx.font=`400 ${font}px Arial,sans-serif`;let count=0;for(const para of String(text||'').split('\n')){let row='';for(const word of para.split(/\s+/)){if(!word)continue;if(ctx.measureText(row?row+' '+word:word).width>w){if(row)count++;row=word;while(ctx.measureText(row).width>w){let cut=row.length-1;while(cut>0&&ctx.measureText(row.slice(0,cut)).width>w)cut--;count++;row=row.slice(Math.max(1,cut));}}else row=row?row+' '+word:word;}count++;}return count;}
function containImage(ctx,im,x,y,w,h){const scale=Math.min(w/im.naturalWidth,h/im.naturalHeight);ctx.drawImage(im,x+(w-im.naturalWidth*scale)/2,y+(h-im.naturalHeight*scale)/2,im.naturalWidth*scale,im.naturalHeight*scale);}
async function drawReportPage(r,pageIndex){const c=document.createElement('canvas');c.width=1190;c.height=1684;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,595,842);const logo=await reportImage(ASSET.logo);ctx.drawImage(logo,34,22,143,63);const total=1+Math.ceil(r.photos.length/4);canvasText(ctx,'H&H RESOURCES / FIELD REPORTS',326,37,235,{font:7.7,color:'#738168',weight:600});ctx.strokeStyle='#dce4d4';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(36,806);ctx.lineTo(559,806);ctx.stroke();canvasText(ctx,`${r.code}  ·  Progress report`,36,817,400,{font:7.3,color:'#89927f'});canvasText(ctx,`${pageIndex+1} / ${total}`,527,817,35,{font:7.3,color:'#89927f'});
 if(pageIndex===0){canvasText(ctx,'PHOTOGRAPHIC PROGRESS RECORD',39,120,520,{font:8,color:'#73876a',weight:600});canvasText(ctx,'Progress report',36,145,523,{font:31,weight:600,color:'#193c2b',line:1.2});canvasText(ctx,r.projectName,38,192,519,{font:19,weight:500,color:'#315139',line:1.3,maxLines:3});const y=284;ctx.fillStyle='#f0f3e9';ctx.fillRect(38,y,519,229);if(r.photos.length){const coverPhoto=r.photos.find(ph=>ph.source===32)||r.photos[r.photos.length-1];const im=await reportImage(coverPhoto.src);containImage(ctx,im,38,y,519,229);}else canvasText(ctx,'No approved photographs',72,y+103,451,{font:12,color:'#7b8b6c'});const meta=(label,value,x,y,w)=>{canvasText(ctx,label,x,y,w,{font:7.3,color:'#8a977e',weight:600});canvasText(ctx,value,x,y+15,w,{font:10,color:'#2b422d',line:1.3,maxLines:3});};meta('REPORTING PERIOD',`${dateLabel(r.from,{day:'numeric',month:'short',year:'numeric'})} — ${dateLabel(r.to,{day:'numeric',month:'short',year:'numeric'})}`,38,552,265);meta('APPROVED PHOTOGRAPHS',String(r.photos.length),345,552,210);meta('PREPARED FOR',r.client,38,600,267);meta('REFERENCE',r.reference||r.code,345,600,210);canvasText(ctx,'OWNER’S REPORT SUMMARY',38,666,519,{font:7.3,color:'#8a977e',weight:600});canvasText(ctx,r.summary||'Photographic record of the owner-reviewed work-stage descriptions.',38,683,518,{font:9,line:1.45,maxLines:8});
 }else{canvasText(ctx,r.projectName,187,72,370,{font:8.5,weight:600,color:'#47623d',maxLines:2,line:1.2});const list=r.photos.slice((pageIndex-1)*4,pageIndex*4);for(let i=0;i<list.length;i++){const ph=list[i],x=36+(i%2)*269,y=108+Math.floor(i/2)*344,w=254,h=332;ctx.strokeStyle='#dce3d5';ctx.lineWidth=.7;ctx.strokeRect(x,y,w,h);ctx.fillStyle='#f1f5eb';ctx.fillRect(x+.4,y+.4,w-.8,27);canvasText(ctx,`PHOTO ${String((pageIndex-1)*4+i+1).padStart(2,'0')}`,x+10,y+9,100,{font:8,weight:600,color:'#4e703e'});canvasText(ctx,dateLabel(ph.date,{day:'numeric',month:'short',year:'numeric'}),x+154,y+9,90,{font:7.3,color:'#748268'});const im=await reportImage(ph.src);ctx.fillStyle='#fafbf7';ctx.fillRect(x+7,y+33,w-14,163);containImage(ctx,im,x+7,y+33,w-14,163);const titleHeight=canvasText(ctx,ph.title,x+10,y+207,w-20,{font:10,weight:600,color:'#294a32',line:1.2,maxLines:2}).height;const captionTop=y+211+titleHeight;const room=(y+306)-captionTop;let font=9.1;while(font>6.3&&measureLines(ctx,ph.caption,w-20,font)*font*1.33>room)font-=.25;canvasText(ctx,ph.caption,x+10,captionTop,w-20,{font,color:'#65745e',line:1.33});canvasText(ctx,`${ph.source?'Source photo '+ph.source+' · ':''}Owner-reviewed`,x+10,y+317,w-20,{font:6.9,color:'#94a087'});}}
 return c;}
/* Minimal PDF 1.4 writer. It embeds A4 canvas pages as JPEG images.
 * No remote renderer or library is required. Raster pages preserve Unicode and
 * the exact preview layout; text is not selectable in this demonstration PDF.
 */
function canvasesToPDF(canvases){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const write=s=>{const b=typeof s==='string'?encoder.encode(s):s;chunks.push(b);length+=b.length;};const object=(n,parts)=>{offsets[n]=length;write(`${n} 0 obj\n`);parts.forEach(write);write('\nendobj\n');};write('%PDF-1.4\n%HNH-REPORT\n');object(1,['<< /Type /Catalog /Pages 2 0 R >>']);const ids=canvases.map((_,i)=>3+i*3);object(2,[`<< /Type /Pages /Count ${canvases.length} /Kids [${ids.map(n=>`${n} 0 R`).join(' ')}] >>`]);canvases.forEach((c,i)=>{const page=ids[i],image=page+1,content=page+2;const binary=atob(c.toDataURL('image/jpeg',.93).split(',')[1]);const data=Uint8Array.from(binary,ch=>ch.charCodeAt(0));const commands='q\n595.28 0 0 841.89 0 0 cm\n/Im0 Do\nQ\n';object(page,[`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${image} 0 R >> >> /Contents ${content} 0 R >>`]);object(image,[`<< /Type /XObject /Subtype /Image /Width ${c.width} /Height ${c.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n`,data,'\nendstream']);object(content,[`<< /Length ${encoder.encode(commands).length} >>\nstream\n${commands}endstream`]);});const xref=length;write(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(let n=1;n<offsets.length;n++)write(`${String(offsets[n]).padStart(10,'0')} 00000 n \n`);write(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
function downloadBlob(blob,filename){const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
let exporting=false;
async function exportReport(snapshot=null){if(!requireOwner()||exporting)return;const r=snapshot||getReportSnapshot();if(!r||!r.photos.length){toast('Approve at least one photo before exporting.','error');return;}if(!r.from||!r.to||r.from>r.to){toast('Choose a valid reporting period.','error');return;}exporting=true;const btn=$('#export-pdf');if(btn){btn.disabled=true;btn.innerHTML=icon('refresh')+' Building PDF…';}toast(`Preparing ${1+Math.ceil(r.photos.length/4)} report pages…`);try{const pages=[];for(let n=0;n<1+Math.ceil(r.photos.length/4);n++){pages.push(await drawReportPage(r,n));await new Promise(resolve=>setTimeout(resolve,0));}const blob=canvasesToPDF(pages);downloadBlob(blob,`HNH_${r.code}_Progress_Report_${r.to}.pdf`);if(!snapshot){S.reports.push(r);addActivity(`exported a progress report with ${r.photos.length} approved photos.`,r.project);await save();}if(!snapshot&&V.page==='report-compose')navigateView({page:'reports',project:null,query:'',reportFilter:'all',reportFrom:'',reportTo:'',reportSort:'newest',reportListPage:1});else if(V.page==='reports')render();toast('PDF downloaded.');}catch(e){toast('PDF export failed. Check that all photos load, then try again.','error');console.error(e);}finally{exporting=false;if(btn){btn.disabled=false;btn.innerHTML=icon('download')+'Export PDF report';}}}

async function installApp(){if(!installPrompt){toast('Installation is not available in this browser.','error');return;}await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;render();}
function updateReviewCard(ph){const card=$(`[data-card="${ph.id}"]`);if(!card)return;const stat=card.querySelector('[data-status]');if(stat)stat.innerHTML=statusBadge(ph.status);const selection=card.querySelector('[data-select]');if(selection){selection.disabled=ph.status!=='review';selection.checked=V.selected.has(ph.id);}card.classList.toggle('selected',V.selected.has(ph.id));const approve=card.querySelector('[data-act="approve-one"]');if(approve){approve.disabled=!ph.caption.trim()||ph.status==='approved';approve.className='btn sm primary';approve.innerHTML=icon('check')+'Approve';}const allApprove=$('[data-act="approve-all"]');if(allApprove)allApprove.disabled=!reviewRows().some(p=>p.status==='review');const el=$('#selected-count');if(el)el.textContent=`${V.selected.size} selected`;const selectedButton=$('[data-act="approve-selected"]');if(selectedButton)selectedButton.disabled=V.selected.size===0;}
async function handleClick(e){const b=e.target.closest('[data-act]');if(!b||b.disabled)return;if(b.tagName==='A'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button))return;e.preventDefault();const a=b.dataset.act,id=b.dataset.id;
 try{switch(a){
 case 'nav':if(V.page!==b.dataset.page||V.project)changePage(b.dataset.page);break;case 'back':goBack();break;
 case 'role':if(uploadBusy||b.dataset.role===V.role)return;if(b.dataset.role==='supervisor'&&!S.supervisors.some(s=>s.active)){toast('No active supervisors.','error');return;}navigateView({role:b.dataset.role,supervisor:sup(V.supervisor)?.active?V.supervisor:S.supervisors.find(s=>s.active)?.id,page:'overview',project:null,tab:'overview',query:'',filter:'all',selected:new Set()});break;
 case 'project-new':projectForm();break;case 'project-edit':projectForm(id);break;
 case 'project-open':if(canAccess(project(id)))changePage('projects',id);else toast('You are not assigned to this project.','error');break;
 case 'tab':if(V.tab!==b.dataset.tab)navigateView({tab:b.dataset.tab});break;
 case 'project-review':if(!requireOwner())return;navigateView({page:'review',project:null,reviewProject:id,reviewFilter:'pending',query:'',selected:new Set()});break;
 case 'project-report':if(!requireOwner())return;navigateView({page:'report-compose',project:null,reportProject:id,reportDraft:null,reportPage:0});break;
 case 'supervisor-new':supervisorForm();break;case 'supervisor-edit':supervisorForm(id);break;
 case 'supervisor-toggle':if(!requireOwner())return;{const s=sup(id);if(!s)return;confirmDialog(s.active?'Deactivate supervisor?':'Activate supervisor?',s.active?`${s.name} will be removed from the demo supervisor selector. Their photographs, project assignments and history will be preserved.`:`${s.name} will be available in the demo supervisor selector again.`,async()=>{s.active=!s.active;await save();render();toast(`${s.name} ${s.active?'activated':'deactivated'}.`);},s.active?'Deactivate':'Activate');}break;
 case 'supervisor-delete':if(!requireOwner())return;{const s=sup(id);if(!s)return;if(S.photos.some(p=>p.supervisor===id)){openModal('Keep the project record intact','This supervisor has submitted project photographs.',`<p class="description" style="font-size:13px">Deleting this profile would orphan the photo record. Deactivate ${esc(s.name)} instead; existing submissions will be retained.</p>`,button('Close','modal-close')+button('Deactivate instead','deactivate-instead','pause','primary',`data-id="${id}"`),'narrow');return;}confirmDialog('Delete supervisor?',`Delete ${s.name}? Their project assignments and pending prompts will be removed.`,async()=>{S.supervisors=S.supervisors.filter(x=>x.id!==id);S.projects.forEach(p=>p.assigned=p.assigned.filter(x=>x!==id));S.notifications=S.notifications.filter(n=>n.to!==id);await save();render();toast('Supervisor deleted.');},'Delete supervisor',true);}break;
 case 'deactivate-instead':if(!requireOwner())return;{const s=sup(id);s.active=false;await save();closeModal();render();toast('Supervisor deactivated. Existing records retained.');}break;
 case 'prompt-now':await sendPrompt(id);break;
 case 'upload-open':uploadForm(id);break;case 'choose-files':$('#upload-files')?.click();break;case 'take-photo':$('#camera-file')?.click();break;
 case 'upload-remove':pendingUploads=pendingUploads.filter(p=>p.id!==id);renderUploadThumbs();break;
 case 'photo-open':photoModal(id);break;case 'photo-clarify':clarificationForm(id);break;
 case 'generate-missing':await generateCaptions(reviewRows().filter(p=>p.status==='queued').map(p=>p.id));break;
 case 'regenerate':if(!requireOwner())return;{const ph=S.photos.find(p=>p.id===id);if(!ph)return;if(ph.caption.trim())confirmDialog('Replace this caption?','Replace the current caption and remove its approval?',()=>generateCaptions([id]),'Regenerate draft');else await generateCaptions([id]);}break;
 case 'approve-one':await approvePhotos([id]);break;case 'approve-selected':approveConfirmation([...V.selected]);break;case 'approve-all':approveConfirmation(reviewRows().filter(p=>p.status==='review').map(p=>p.id));break;
 case 'request-changes':requestChanges(id);break;
 case 'report-open':if(!requireOwner())return;navigateView({page:'report-view',project:null,reportId:id,reportPage:0});break;
 case 'report-clear':V.query='';V.reportFilter='all';V.reportFrom='';V.reportTo='';V.reportListPage=1;syncHistoryEntry();render();break;
 case 'archive-prev':V.reportListPage--;syncHistoryEntry();render();break;case 'archive-next':V.reportListPage++;syncHistoryEntry();render();break;
 case 'report-prev':V.reportPage--;syncHistoryEntry();await refreshReportPreview();break;case 'report-next':V.reportPage++;syncHistoryEntry();await refreshReportPreview();break;
 case 'report-export':await exportReport();break;
 case 'report-redownload':{const r=S.reports.find(r=>r.id===id);if(r)await exportReport(r);}break;
 case 'report-delete':if(!requireOwner())return;confirmDialog('Delete report?','Delete this saved report? Downloaded PDF files will not be affected.',async()=>{S.reports=S.reports.filter(r=>r.id!==id);await save();render();toast('Report deleted.');},'Delete report',true);break;
 case 'inbox':changePage('inbox');break;
 case 'notifications-read':S.notifications.filter(n=>canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).forEach(n=>n.read=true);await save();render();toast('Visible notifications marked as read.');break;
 case 'modal-close':closeModal();break;
 case 'confirm-action':{const fn=confirmCallback;closeModal();if(fn)await fn();}break;
 case 'install':await installApp();break;
 }}catch(err){console.error(err);toast('That action could not be completed. Please try again.','error');}}
let searchTimer,reportTimer;
document.addEventListener('click',handleClick);
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='search'){V.query=el.value;V.reportListPage=1;const start=el.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{syncHistoryEntry();render();const field=$('#search');field?.focus();field?.setSelectionRange(start,start);},180);}
 if(el.dataset.caption&&isOwner()){const ph=S.photos.find(p=>p.id===el.dataset.caption);if(!ph)return;const previous=ph.status;ph.caption=el.value;ph.status=ph.caption.trim()?'review':'queued';ph.approvedBy=null;ph.approvedAt=null;ph.revision++;V.selected.delete(ph.id);updateReviewCard(ph);scheduleSave();if(previous==='approved')toast('Caption updated. Approval required.');}
 if(el.dataset.uploadNote){const ph=pendingUploads.find(p=>p.id===el.dataset.uploadNote);if(ph)ph.note=el.value;}
 const draftKeys={'report-from':'from','report-to':'to','report-client':'client','report-ref':'reference','report-summary':'summary'};
 if(draftKeys[el.id]&&V.page==='report-compose'){const d=ensureReportDraft();d[draftKeys[el.id]]=el.value;V.reportPage=0;syncHistoryEntry();clearTimeout(reportTimer);reportTimer=setTimeout(refreshReportPreview,220);}
});
document.addEventListener('change',async e=>{
 const el=e.target;
 switch(el.id){
 case 'identity':if(sup(el.value)?.active)navigateView({supervisor:el.value,page:'overview',project:null,tab:'overview',query:'',filter:'all',selected:new Set()});break;
 case 'project-filter':case 'photo-filter':case 'team-filter':V.filter=el.value;syncHistoryEntry();render();break;
 case 'review-project':V.reviewProject=el.value;V.selected.clear();syncHistoryEntry();render();break;
 case 'review-status':V.reviewFilter=el.value;V.selected.clear();syncHistoryEntry();render();break;
 case 'select-all':V.selected.clear();if(el.checked)reviewRows().filter(p=>p.status==='review').forEach(p=>V.selected.add(p.id));syncHistoryEntry();render();break;
 case 'f-cadence':$('#weekday-field')?.classList.toggle('hidden',el.value!=='weekly');$('#interval-field')?.classList.toggle('hidden',el.value!=='interval');break;
 case 'upload-files':case 'camera-file':await addFiles(el.files);el.value='';break;
 case 'report-project':navigateView({reportProject:el.value,reportDraft:null,reportPage:0},{replace:true});break;
 case 'archive-project':V.reportFilter=el.value;V.reportListPage=1;syncHistoryEntry();render();break;
 case 'archive-from':V.reportFrom=el.value;V.reportListPage=1;syncHistoryEntry();render();break;
 case 'archive-to':V.reportTo=el.value;V.reportListPage=1;syncHistoryEntry();render();break;
 case 'archive-sort':V.reportSort=el.value;V.reportListPage=1;syncHistoryEntry();render();break;
 }
 if(el.dataset.select){if(el.checked)V.selected.add(el.dataset.select);else V.selected.delete(el.dataset.select);const card=el.closest('.review-card');card?.classList.toggle('selected',el.checked);const count=$('#selected-count');if(count)count.textContent=`${V.selected.size} selected`;const btn=$('[data-act="approve-selected"]');if(btn)btn.disabled=V.selected.size===0;syncHistoryEntry();}
});
document.addEventListener('submit',async e=>{const form=e.target;if(!['project-form','supervisor-form','upload-form','changes-form','clarify-form'].includes(form.id))return;e.preventDefault();try{if(form.id==='project-form')await saveProject(form);if(form.id==='supervisor-form')await saveSupervisor(form);if(form.id==='upload-form')await submitUpload(form);if(form.id==='changes-form'){if(!requireOwner())return;const ph=S.photos.find(p=>p.id===form.dataset.id),reason=new FormData(form).get('reason').trim();if(!ph||!reason)return;ph.status='rejected';ph.rejection=reason;ph.approvedBy=null;ph.approvedAt=null;V.selected.delete(ph.id);S.notifications.push({id:uid('n'),project:ph.project,to:ph.supervisor,photo:ph.id,kind:'clarification',text:`Clarification requested for “${ph.title}”: ${reason}`,created:stamp(),read:false,fulfilled:false});addActivity('requested clarification on a photo caption.',ph.project);await save();closeModal();render();toast('Clarification request added to the supervisor inbox.');}if(form.id==='clarify-form'){const ph=S.photos.find(p=>p.id===form.dataset.id),note=new FormData(form).get('note').trim();if(!ph||!note||isOwner()||ph.supervisor!==V.supervisor||!canAccess(project(ph.project)))return;ph.note=note;ph.caption=draftCaption(ph);ph.status='review';ph.approvedAt=null;ph.approvedBy=null;ph.revision++;delete ph.rejection;S.notifications.forEach(n=>{if(n.kind==='clarification'&&n.photo===ph.id&&n.to===V.supervisor){n.fulfilled=true;n.read=true;}});addActivity('clarified a photo and resubmitted it for owner review.',ph.project);await save();closeModal();render();toast('Updated note and draft sent back for owner review.');}}catch(err){console.error(err);toast('The form could not be saved. Please try again.','error');}});
document.addEventListener('keydown',e=>{if(!$('.modal')&&['Enter',' '].includes(e.key)&&e.target.matches('[data-act][role=link]')){e.preventDefault();e.target.click();return;}if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tab=e.target.dataset.tab==='overview'?'photos':'overview';navigateView({tab});document.getElementById('tab-'+tab)?.focus();return;}const modal=$('.modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const els=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]):not([hidden]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render()});
window.addEventListener('online',()=>toast('Connection restored.'));
window.addEventListener('offline',()=>toast('You are offline.'));
window.addEventListener('pagehide',()=>{if(saveTimer){clearTimeout(saveTimer);save();}});
(async()=>{try{await initStore();initNavigation();render();if(!window.HNH_STANDALONE&&'serviceWorker'in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache unavailable',err));}}catch(e){console.error(e);$('#app').innerHTML='<main style="padding:40px"><h1>The workspace could not open</h1><p>Please reload this page in a current browser.</p></main>';}})();
